        i = 0
        while i < len(t) - 1:
            if t[i] == t[i + 1]:
                t_good = False
                break
            i += 1

        if not t_good:
            # only s can be used
            s_good = True
            j = 0
            while j < len(s) - 1:
                if s[j] == s[j + 1]:
                    s_good = False
                    break
                j += 1
            out_lines.append("YES" if s_good else "NO")
        else:
            # BFS over states (pos_in_s, last_char)
            visited = set()
            q = deque()
            start = (0, None)
            visited.add(start)
            q.append(start)
            found = False
            while q:
                pos, last = q.popleft()

                # consume next character from s
                if pos < len(s):
                    nxt = s[pos]
                    if last is None or nxt != last:
                        state = (pos + 1, nxt)
                        if state not in visited:
                            visited.add(state)
                            q.append(state)

                # insert t
                if last is None or last != t[0]:
                    state = (pos, t[-1])
                    if state not in visited:
                        visited.add(state)
                        q.append(state)

                if found:
                    break

            out_lines.append("YES" if found else "NO")
        else:
            # BFS with both options
            visited = set()
            q = deque()
            start = (0, None)
            visited.add(start)
            q.append(start)
            found = False
            while q:
                pos, last = q.popleft()

                # consume next character from s
