def solve():
    sys.setrecursionlimit(1000000)
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    b = [int(next(it)) for _ in range(m)]

    # Precompute factorials and inverse factorials
    max_val = max(max(a) if a else 0, max(b) if b else 0)
    fact = [1] * (max_val + 1)
    for i in range(1, max_val + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (max_val + 1)
    inv_fact[max_val] = pow(fact[max_val], MOD - 2, MOD)
    for i in range(max_val, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

    # Build adjacency list for bipartite graph
    adj = [[] for _ in range(n)]
    for i in range(n):
        ai = a[i]
        for j in range(m):
            if ai % b[j] == 0:
                adj[i].append(j)

    # Hopcroft–Karp algorithm
    pairU = [-1] * n
    pairV = [-1] * m
    dist = [0] * n

    def bfs():
        queue = []
        for u in range(n):
            if pairU[u] == -1:
                dist[u] = 0
                queue.append(u)
            else:
                dist[u] = -1
        found = False
        for u in queue:
            for v in adj[u]:
                pu = pairV[v]
                if pu != -1 and dist[pu] == -1:
                    dist[pu] = dist[u] + 1
                    queue.append(pu)
                elif pu == -1:
                    found = True
        return found

    def dfs(u):
        for v in adj[u]:
            pu = pairV[v]
            if pu == -1 or (dist[pu] == dist[u] + 1 and dfs(pu)):
                pairU[u] = v
                pairV[v] = u
                return True
        dist[u] = -1
        return False

    matching = 0
    while bfs():
        for u in range(n):
            if pairU[u] == -1 and dfs(u):
                matching += 1

    # Count distinct values
    cntA = {}
    for x in a:
        cntA[x] = cntA.get(x, 0) + 1
    cntB = {}
    for x in b:
        cntB[x] = cntB.get(x, 0) + 1

    # Compute product of factorials of counts
    prodA = 1
    for v in cntA.values():
        prodA = prodA * fact[v] % MOD
    prodB = 1
    for v in cntB.values():
        prodB = prodB * fact[v] % MOD

    # Compute answer
    ans = fact[n] * fact[m] % MOD
    ans = ans * pow(prodA, MOD - 2, MOD) % MOD
    ans = ans * pow(prodB, MOD - 2, MOD) % MOD
    ans = ans * pow(fact[matching], MOD - 2, MOD) % MOD

    print(ans)

